function errorCode(r:{ok:boolean;error?:string}):string|undefined{return r.ok?undefined:r.error;}

function test(name:string,fn:()=>void){try{fn();console.log('PASS '+name)}catch(e){console.error('FAIL '+name,e);throw e}}
let checks=0;
test('parseTime accepted forms and rejects malformed, negative, empty and over-48-hour values',()=>{
 for(const [s,ms] of [['83.5',83500],['1:23.5',83500],['01:02:03',3723000],['1h2m3s',3723000],['2m',120000],['0',0]] as const){const r=parseTime(s);assert.equal(r.ok,true);if(r.ok)assert.equal(r.milliseconds,ms);checks++;}
 for(const s of ['', '-1','49:00:00','1:99','1m2h','banana','1::2','Infinity','1h1h']){assert.equal(parseTime(s).ok,false);checks++;}
});
test('300 independent Python-generated fractional and integer FPS cases',()=>{
 const cases=JSON.parse(frameExpected) as {fps:number;durationMs:number;n:number;frames:number[];times:number[]}[];
 assert.equal(cases.length,300);
 for(const c of cases){const r=planFrames({durationMs:c.durationMs,fps:c.fps,width:100,height:100},{mode:'everyNFrames',n:c.n},'high');assert.equal(r.ok,true);if(r.ok){assert.deepEqual(r.frames.map(f=>f.frameNumber),c.frames);assert.deepEqual(r.frames.map(f=>f.timeMs),c.times);}checks++;}
});
test('all modes, exclusive ranges, duplicates, invalid inputs and tier caps',()=>{
 const v={durationMs:10000,fps:25,width:640,height:480};
 const all=planFrames(v,{mode:'all'});assert.equal(all.ok,true);if(all.ok)assert.equal(all.frames.length,250);
 const secs=planFrames(v,{mode:'everyNSeconds',seconds:0.5});assert.equal(secs.ok,true);if(secs.ok)assert.equal(secs.frames.length,20);
 const count=planFrames(v,{mode:'count',count:2});assert.equal(count.ok,true);if(count.ok){assert.equal(count.frames[0].frameNumber,0);assert.equal(count.frames[1].frameNumber,249);}
 const specific=planFrames(v,{mode:'specific',frames:[5,5,250,-1],timesMs:[200,200]});assert.equal(specific.ok,true);if(specific.ok){assert.deepEqual(specific.frames.map(f=>f.frameNumber),[5]);assert.ok(specific.skipped.length>=4);}
 assert.equal(planFrames({...v,fps:0},{mode:'all'}).ok,false);assert.equal(planFrames(v,{mode:'everyNFrames',n:0}).ok,false);assert.equal(planFrames(v,{mode:'everyNSeconds',seconds:0.0001}).ok,false);assert.equal(planFrames(v,{mode:'count',count:0}).ok,false);assert.equal(planFrames(v,{mode:'all',range:{startMs:9000,endMs:9000}}).ok,false);
 assert.equal(maxFramesForTier('low'),300);assert.equal(maxFramesForTier('mid'),1500);assert.equal(maxFramesForTier('high'),5000);
 for(const tier of ['low','mid','high'] as const){const r=planFrames({durationMs:3*3600*1000,fps:60,width:1,height:1},{mode:'everyNFrames',n:1},tier);assert.equal(r.ok,false);if(!r.ok){assert.equal(r.error,'too-many');assert.ok(r.suggestion?.length);}}
 const hugeSpecific=planFrames(v,{mode:'specific',frames:Array.from({length:20001},(_,i)=>i)});assert.equal(hugeSpecific.ok,false);
 checks+=18;
});
test('file names sanitize paths/control characters, keep unicode, and stay unique',()=>{
 const frames=[{index:0,frameNumber:123,timeMs:5120},{index:1,frameNumber:123,timeMs:5120}];const r=frameFileNames('../💛/\u0000clip',frames,'png');assert.equal(r.ok,true);if(r.ok){assert.equal(r.names.length,2);assert.notEqual(r.names[0],r.names[1]);assert.ok(r.names[0].includes('💛clip_f000123_00-00-05.120.png'));}assert.equal(frameFileNames('',[],'gif' as 'png').ok,false);checks+=3;
});
test('run state machine enforces issue/complete, memory cap, drain, cancel and ZIP duplicates',()=>{
 const p=planFrames({durationMs:1000,fps:2,width:1,height:1},{mode:'all'});assert.equal(p.ok,true);if(!p.ok)return;const run=createFrameRun(p,{maxHeldBytes:2});const first=run.next();assert.ok(first);if(!first)return;assert.equal(errorCode(run.complete(first.index,{ok:true,bytes:new Uint8Array([1,2,3])})),'memory-cap');assert.equal(run.complete(first.index,{ok:true,bytes:new Uint8Array([1])}).ok,true);assert.equal(errorCode(run.complete(first.index,{ok:true})),'already-completed');assert.equal(run.snapshot().heldBytes,1);assert.equal(run.drain().length,1);const second=run.next();assert.ok(second);if(second){run.complete(second.index,{ok:false,message:'bad'});assert.equal(run.snapshot().state,'done');assert.equal(run.snapshot().done+run.snapshot().failed+run.snapshot().remaining,run.snapshot().total);}const cancelled=createFrameRun(p);cancelled.cancel();assert.equal(cancelled.next(),null);assert.equal(errorCode(cancelled.complete(0,{ok:true})),'after-cancel');assert.equal(errorCode(zipEntries([{name:'a.png',bytes:new Uint8Array()},{name:'A.PNG',bytes:new Uint8Array()}])),'duplicate-name');checks+=12;
});
// Fixed-seed 2,000-operation state-machine walk. Each step checks conservation of the total.
test('seeded 2,000-operation state walk preserves done + failed + remaining = total',()=>{
 const p=planFrames({durationMs:1000,fps:20,width:1,height:1},{mode:'all'});assert.equal(p.ok,true);if(!p.ok)return;const run=createFrameRun(p,{maxHeldBytes:100000});let seed=0x20c20;const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed;};const issued:number[]=[];
 for(let i=0;i<2000;i++){const op=rnd()%4;if(op===0){const f=run.next();if(f)issued.push(f.index);}else if(op===1&&issued.length){const idx=issued[rnd()%issued.length];run.complete(idx,{ok:(rnd()%5)!==0,bytes:new Uint8Array(rnd()%3)});}else if(op===2){run.drain();}else{const s=run.snapshot();assert.equal(s.done+s.failed+s.remaining,s.total);}const s=run.snapshot();assert.equal(s.done+s.failed+s.remaining,s.total);checks++;}
});
console.log(`framePlan checks: ${checks}`);
test('mutation checks reject five common broken implementations',()=>{
 const v={durationMs:2000,fps:25,width:10,height:10};const p=planFrames(v,{mode:'everyNFrames',n:10});assert.equal(p.ok,true);if(!p.ok)return;
 assert.notDeepEqual(p.frames.map(f=>f.frameNumber),[1,11,21,31,41]); // mutant: starts at frame 1
 assert.notEqual(p.frames[1].timeMs,4001); // mutant: time unit conversion off by 10x
 assert.notEqual(p.estimate.estimatedPngBytes,p.frames.length*100); // mutant: forget 4-byte pixels
 assert.notEqual(frameFileNames('x',p.frames.slice(0,1),'png').ok,false); // mutant: reject valid format
 const r=createFrameRun(p,{maxHeldBytes:0});const f=r.next();assert.ok(f);if(f)assert.equal(errorCode(r.complete(f.index,{ok:true,bytes:new Uint8Array([1])})),'memory-cap');checks+=5;
});
